413→interface KanbanBoardProps {
414→  projects: Project[]
415→  navigateToProject: (id: string) => void
416→  deleteMutation: { mutate: (id: string) => void; isPending: boolean }
417→  statusMutation: { mutate: (data: { projectId: string; status: string; comment?: string }) => void; isPending: boolean }
418→  formatDate: (d: string) => string
419→  readinessMap: Record<string, ProjectReadinessResponse>
420→}
