422→function KanbanBoard({ projects, navigateToProject, deleteMutation, statusMutation, formatDate, readinessMap }: KanbanBoardProps) {
423→  const { toast } = useToast()
424→
425→  const projectsByStatus = useMemo(() => {
426→    const map = new Map<string, Project[]>()
427→    KANBAN_COLUMNS.forEach((col) => map.set(col.status, []))
428→    projects.forEach((p) => {
429→      const list = map.get(p.status)
430→      if (list) {
431→        list.push(p)
432→      } else {
433→        // Unknown status → put in "new" column
434→        const newList = map.get('new')
435→        if (newList) newList.push(p)
436→      }
437→    })
438→    return map
439→  }, [projects])
440→
441→  // DnD sensors - PointerSensor for mouse, TouchSensor for mobile
442→  const sensors = useSensors(
443→    useSensor(PointerSensor, {
444→      activationConstraint: {
445→        distance: 5, // 5px movement required to start drag
446→      },
447→    }),
448→    useSensor(TouchSensor, {
449→      activationConstraint: {
450→        delay: 250, // 250ms long press to start drag on touch devices
451→        tolerance: 5,
452→      },
453→    })
454→  )
455→
456→  // Track active item for DragOverlay
457→  const [activeId, setActiveId] = useState<string | null>(null)
458→  const activeProject = projects.find((p) => p.id === activeId)
459→
460→  // onDragEnd handler
461→  const handleDragEnd = async (event: { active: { id: string }; over: { id: string } | null }) => {
462→    const { active, over } = event
463→    setActiveId(null)
464→
465→    if (!over) {
466→      console.log('[DnD] Drag ended outside any droppable zone')
467→      return
468→    }
469→
470→    const projectId = active.id
471→    const targetStatus = over.id
472→
473→    // Find current project to get its current status
474→    const project = projects.find((p) => p.id === projectId)
475→    if (!project) {
476→      console.error('[DnD] Project not found:', projectId)
477→      toast({ title: 'Ошибка', description: 'Проект не найден', variant: 'destructive' })
478→      return
479→    }
480→
481→    const currentStatus = project.status
482→
483→    // Skip if dropping in the same column
484→    if (currentStatus === targetStatus) {
485→      console.log('[DnD] Dropped in same column, no action needed')
486→      return
487→    }
488→
489→    console.log(`[DnD] Drag: ${project.name} (${currentStatus}) → ${targetStatus}`)
490→
491→    // Validate transition
492→    const validTargets = VALID_TRANSITIONS[currentStatus] || []
493→    if (!validTargets.includes(targetStatus)) {
494→      console.warn(`[DnD] Invalid transition: ${currentStatus} → ${targetStatus}`)
495→      toast({
496→        title: 'Недопустимый переход',
497→        description: `Нельзя изменить статус с "${STATUS_MAP[currentStatus]?.label || currentStatus}" на "${STATUS_MAP[targetStatus]?.label || targetStatus}"`,
498→        variant: 'destructive',
499→      })
500→      return
501→    }
502→
503→    // Use React Query mutation for status update
504→    statusMutation.mutate(
505→      { projectId, status: targetStatus },
506→      {
507→        onSuccess: () => {
508→          toast({
509→            title: 'Статус обновлён',
510→            description: `${project.name} → ${STATUS_MAP[targetStatus]?.label || targetStatus}`,
511→          })
512→          console.log(`[DnD] Status updated successfully: ${projectId} → ${targetStatus}`)
513→        },
514→      }
515→    )
516→  }
517→
518→  const handleDragStart = (event: { active: { id: string } }) => {
519→    setActiveId(event.active.id)
520→    console.log('[DnD] Drag started:', event.active.id)
521→  }
522→
523→  return (
524→    <DndContext
525→      sensors={sensors}
526→      collisionDetection={closestCenter}
527→      onDragStart={handleDragStart}
528→      onDragEnd={handleDragEnd}
529→    >
530→      <div className="overflow-x-auto pb-4 -mx-2">
531→        <div className="flex gap-4 min-w-max px-2">
532→          {KANBAN_COLUMNS.map((col) => {
533→            const columnProjects = projectsByStatus.get(col.status) ?? []
534→            return (
535→              <KanbanColumn
536→                key={col.status}
537→                col={col}
538→                columnProjects={columnProjects}
539→                navigateToProject={navigateToProject}
540→                deleteMutation={deleteMutation}
541→                formatDate={formatDate}
542→              />
543→            )
544→          })}
545→        </div>
546→      </div>
547→
548→      {/* Drag Overlay - visual feedback during drag */}
549→      <DragOverlay>
550→        {activeProject && (() => {
551→          const col = KANBAN_COLUMNS.find((c) => c.status === activeProject.status) ?? KANBAN_COLUMNS[0]
552→          const budget = (activeProject.items ?? []).reduce((sum, item) => sum + item.price * item.quantity, 0)
553→          const itemCount = activeProject._count?.items ?? 0
554→
